    io.writeln('media slots (no override = main connection):');
    for (final slot in mediaModelSlotIds) {
      final override = models?.slots[slot];
      if (override == null) {
        io.writeln('  $slot: main connection');
      } else {
        final key = override.apiKeyName == null
