  void _setModelsSlot(String args) {
    final parts = args
        .split(RegExp(r'\s+'))
        .where((part) => part.isNotEmpty)
        .toList();
    if (parts.length < 2 || parts.length > 3) {
      io.writeln('usage: /models set <slot> <model> [baseUrl]');
      return;
    }
    final slot = parts[0];
    if (!mediaModelSlotIds.contains(slot)) {
      io.writeln(
