        // different profile's endpoint) would otherwise clobber this
        // switch's key on the next model pick.
        _apiKey = token ?? _providerKeyFor(spec, baseUrl) ?? '';
        try {
          rolesResolver.setDefaultChain([
            ModelRef(
              provider: spec.name,
              modelId: modelId,
              baseUrl: baseUrl,
              apiKeyName: pinnedKeyName,
              authHeader: authHeader,
            ),
          ]);
          rolesResolver.applyToAgent(_agent);
        } on ConfigException catch (error) {
          io.writeln('cannot switch provider: ${error.message}');
          return;
        }
        _streamFunction = _agent.streamFunction;
        _modelCache = const [];
        _modelContextWindows = const {};
        _modelMaxTokens = const {};
        _lastModelList = null;
        await _session?.appendModelChange(
          provider: spec.name,
          modelId: modelId,
          // A LIVE switch records the pin too: the session's own last
          // model_change must re-bind to THIS entry on restore — the shared
