    // shared kind with neither is identity-less — reject instead of
    // silently riding the legacy openrouter default (M5).
    final effectiveBaseUrl = _resolveBaseUrl(
      baseUrl: baseUrl,
      spec: spec,
      name: name,
      rawKind: rawKind,
