/// Wire ⇄ endpoint: a KNOWN endpoint of another dialect is a rejection.
/// Unknown endpoints pass — there is nothing declared to check against.
void _validateWireEndpoint({
  required String wireKind,
  required String baseUrl,
  required String modelId,
}) {
  for (final spec in providerCatalog.values) {
    if (spec.kind == wireKind) continue;
    if (spec.defaultBaseUrl.isEmpty) continue;
    if (!sameEndpoint(spec.defaultBaseUrl, baseUrl)) continue;
    throw ConfigException(
      'provider/model binding mismatch: model "$modelId" would ride wire '
      '"$wireKind" against ${spec.name}\'s endpoint $baseUrl — that '
      'endpoint speaks the "${spec.kind}" wire. Point the binding at the '
      'matching endpoint, or declare the explicit `wire:` override only '
      'when the endpoint genuinely speaks "$wireKind"',
    );
  }
}

