168:        wireKind: wireKind,
169:        baseUrl: effectiveBaseUrl,
170:        modelId: modelId,
171:      );
172:      _validateModelEndpoint(
173:        wireKind: wireKind,
174:        spec: spec,
175:        baseUrl: effectiveBaseUrl,
