        () => ProviderModelBinding.resolve(
          providerKind: 'anthropic',
          modelId: 'gpt-5',
          provenance: BindingProvenance.flag,
        ),
        throwsA(
          isA<ConfigException>().having(
            (e) => e.message,
            'message',
            allOf(contains('gpt-5'), contains('api.anthropic.com')),
