    });

    test('a known google family id over an openai endpoint is rejected', () {
      expect(
        () => ProviderModelBinding.resolve(
          providerKind: 'openrouter',
          modelId: 'gemini-2.5-pro',
          provenance: BindingProvenance.flag,
        ),
