/// anthropic.com serves only claude ids, api.openai.com only gpt ids,
/// generativelanguage.googleapis.com only gemini ids — routers like
/// OpenRouter/Copilot/DIAL and unknown endpoints serve many families and
/// are never judged). Unknown ids or unknown endpoints pass (D2
/// territory, never a guess).
void _validateModelEndpoint({
  required ProviderSpec spec,
  required String baseUrl,
  required String modelId,
}) {
