+  if (hint == null || hint == spec.api) return;
+  // The family check fires only on a family-EXCLUSIVE canonical
+  // endpoint: routers (OpenRouter, Copilot, DIAL, kimi, …) and unknown
+  // endpoints serve many families and carry no verdict.
