    ('openai', 'openai-completions'),
    ('google', 'google-generative-ai'),
  ]) {
    final spec = providerCatalog[entry.$1];
    if (spec == null || spec.defaultBaseUrl.isEmpty) continue;
    if (sameEndpoint(spec.defaultBaseUrl, baseUrl)) verdict = entry.$2;
