      final b = ProviderModelBinding.resolve(
        providerKind: 'kimi',
        modelId: 'kimi-k2',
        recordName: 'kimi',
        provenance: BindingProvenance.command,
      );
      expect(a, equals(b));
      expect(a.hashCode, b.hashCode);
    });

    test('echo names record, wire, endpoint and model (I2 report shape)', () {
