ModelRolesResolver? rolesResolver;
var defaultRoleResolved = false;
if (rolesConfig != null) {
  rolesResolver = ModelRolesResolver(
    config: rolesConfig,
    secrets: roleSecrets,
    cwd: cwd,
    homeDir: home,
