test('parses and round-trips authHeader (issue #964)', () {
  final ref = ModelRef.fromYaml(
    _yaml(
      'provider: openai\nmodel: gpt-4o\n'
      'baseUrl: https://gateway.example.com/v1\n'
      'authHeader: x-api-key\n',
    ),
  );
